import fs from "fs";
import { addressSentence, lineFrom, hexOf, narrate, DIMENSIONS } from "./sentence.js";
import { makeParticle } from "./particle.js";
import { Field } from "./emergent.js";
let pass = 0, fail = 0; const ok = (n, c) => { c ? pass++ : fail++; console.log(`${c ? "PASS" : "FAIL"}  ${n}`); };
ok("every dimension has 6 chain terms and 5 natures", Object.values(DIMENSIONS).every(d => d.chain.length === 6 && d.natures.length === 5));
ok("Movement line 1 = Movement (bottom), line 6 = Environment", DIMENSIONS.Movement.chain[0] === "Movement" && DIMENSIONS.Movement.chain[5] === "Environment");
ok("own frame reads straight; Movement reading Being crosses (1 <-> 6)", lineFrom("Being", "Being", 1) === 1 && lineFrom("Movement", "Being", 1) === 6 && lineFrom("Movement", "Being", 6) === 1);
ok("same-facing frames read straight (Movement <-> Evolution)", lineFrom("Movement", "Evolution", 2) === 2);
const g1 = Array.from({ length: 400 }, (_, i) => makeParticle(i, i * 0.9)).find(p => p.gate === 1 && p.line === 6);
const s = addressSentence(g1, { frame: g1.dress.dimension });
console.log("   e.g.", s.sentence);
ok("gate 1 line 6 in its own frame reads the sixth term of its chain", s.term === DIMENSIONS[g1.dress.dimension].chain[5]);
const m = addressSentence({ ...g1, dress: { ...g1.dress, dimension: "Movement" } });
console.log("   e.g.", m.sentence);
ok("gate 1 (the Creative) line 6 from Movement: I Create — Environment", m.sentence.startsWith("I Create — Environment"));
ok("hex is 4 digits from hexagram bits + color/tone/base", /^[0-9A-F]{4}$/.test(hexOf(g1)));
ok("attractor relation is stated", addressSentence(g1, { attractor: g1 }).sentence.includes("IS the attractor"));
const prior = JSON.parse(fs.readFileSync(new URL("../bhantugh_rules.json", import.meta.url))).channels;
const F = new Field(Array.from({ length: 160 }, (_, i) => makeParticle(i + 1, (i * 97.31 + 13) % 360, { body: i % 13 })), prior);
for (let i = 0; i < 10; i++) F.step();
const story = narrate(F);
story.slice(0, 4).forEach(x => console.log("   swarm:", x.sentence));
ok(`the swarm narrates its own events (${story.length} sentences, ${new Set(story.map(x => x.frame)).size} frames)`, story.length > 0);
console.log(`\n${pass} passed, ${fail} failed`); process.exit(fail ? 1 : 0);
